#ifndef EQEMU_HOUSING_LAYOUT_RETAINED_TOKEN_OUTCOME_DB_H
#define EQEMU_HOUSING_LAYOUT_RETAINED_TOKEN_OUTCOME_DB_H
#include "layout_property_outcome_db.h"
#include "layout_retained_token_types.h"
namespace Housing::LayoutRetained {
struct Outcome {uint16_t operation_index=0;int32_t serial=0;std::string child_key;CustodyCodec::Bytes child_outcome;LiveItems::InventoryRow source;uint64_t house_before_id=0,house_before_revision=0;LayoutCrate::Allocation crate_before;LayoutPropertyOutcome::Snapshot after;};
namespace Detail {
using namespace LayoutPropertyOutcome::Detail;
inline void Shape(const Outcome& t){
 Require(t.serial>0&&t.operation_index<UINT16_MAX&&!t.child_key.empty()&&t.child_key.size()<=96&&!t.child_outcome.empty()&&t.child_outcome.size()<=262144&&CustodyCodec::Valid(t.source));LayoutPropertyOutcome::Detail::Shape(t.after);const auto& a=t.after;const auto& s=a.placement.stored;
 Require(bool(t.house_before_id)!=bool(t.crate_before)&&bool(t.house_before_id)==bool(t.house_before_revision)&&bool(a.house)==bool(t.house_before_id)&&bool(a.crate)==bool(t.crate_before)&&!a.member&&!a.stackable&&!s.stowed&&CustodyCodec::Encode(t.source)==CustodyCodec::Encode(s.row)&&a.runtime_serial==t.serial&&t.source.values.character_id==a.creator&&t.source.values.slot_id>=23&&t.source.values.slot_id<=33);
 if(a.house)Require(a.house->house_id==t.house_before_id&&t.house_before_revision!=UINT64_MAX&&a.house->revision==t.house_before_revision+1&&!a.placement.room);
 if(a.crate){const auto& b=*t.crate_before;Require(!b.packed&&!a.crate->packed&&b.inventory_character_id==t.source.values.character_id&&b.inventory_slot_id==t.source.values.slot_id&&b.binding.crate_id==a.crate->binding.crate_id&&b.binding.revision!=UINT64_MAX&&a.crate->binding.revision==b.binding.revision+1&&b.binding.native_estate_id==a.crate->binding.native_estate_id&&b.created_by_character_id==a.crate->created_by_character_id&&b.binding.item_template_id==a.crate->binding.item_template_id&&b.binding.definition_id==a.crate->binding.definition_id);}
}
}
inline CustodyCodec::Bytes Encode(const Outcome& t){Detail::Shape(t);CustodyCodec::Bytes b;CustodyCodec::W(b,1,4);CustodyCodec::W(b,t.operation_index,2);CustodyCodec::W(b,uint32_t(t.serial),4);CustodyCodec::S(b,t.child_key);LayoutInventory::OutcomeDetail::Blob(b,t.child_outcome);LayoutInventory::OutcomeDetail::Row(b,t.source);CustodyCodec::W(b,t.house_before_id,8);CustodyCodec::W(b,t.house_before_revision,8);CustodyCodec::W(b,bool(t.crate_before),1);if(t.crate_before)LayoutInventory::OutcomeDetail::Blob(b,CrateBinding::EncodeAllocation(*t.crate_before));LayoutPropertyOutcome::Detail::Write(b,t.after,true,true,true);return b;}
inline Outcome Decode(const CustodyCodec::Bytes& b){CustodyCodec::Reader r{b};Detail::Require(r.N(4)==1);Outcome t;t.operation_index=r.N(2);const auto serial=r.N(4);Detail::Require(serial<=INT32_MAX);t.serial=serial;t.child_key=r.Text(96);t.child_outcome=r.Blob(262144);t.source=LayoutInventory::OutcomeDetail::Row(r);t.house_before_id=r.N(8);t.house_before_revision=r.N(8);if(LayoutInventory::OutcomeDetail::Flag(r)){auto a=CrateBinding::DecodeAllocation(r.Blob(512));Detail::Require(bool(a));t.crate_before=std::make_shared<CrateBinding::Allocation>(std::move(a.value));}t.after=LayoutPropertyOutcome::Detail::Read(r,true,true,true);Detail::Require(r.at==b.size()&&Encode(t)==b);return t;}
inline bool Matches(const Outcome& t,const Witness& w){try{Detail::Shape(t);return t.operation_index==w.operation_index&&t.serial==w.serial&&CustodyCodec::Encode(t.source)==CustodyCodec::Encode(w.row)&&t.house_before_id==w.house_id&&(t.crate_before?t.crate_before->binding.crate_id:0)==w.crate_id&&w.original&&w.original->GetSerialNumber()==w.serial&&Typed(w.original)&&w.original->GetHousingHouseID()==w.house_id&&w.original->GetHousingCrateID()==w.crate_id&&w.original->GetHousingEstateID()==(t.after.house?t.after.house->interior->native_estate_id:t.after.crate->binding.native_estate_id)&&LayoutCrate::Matches(t.after.crate,w.original)&&LayoutHouse::Matches(t.after.house,w.original)&&InventoryProjection::Matches(w.row,*w.original);}catch(...){return false;}}
inline LiveItems::Result<bool> ValidateUnderTransaction(Database& db,const LiveItems::Lease& lease,const Outcome& t,const std::string& parent_key){
 try{Detail::Shape(t);Detail::Require(t.child_key==LayoutProperty::Detail::Key(parent_key,t.operation_index,"inventory")&&t.after.creator==lease.actor.character_id&&t.after.account==lease.actor.account_id&&t.after.epoch==lease.epoch&&t.after.session==lease.session_key&&!t.after.reservation_house_revision&&t.after.scope_revision==(t.after.placement.room?1:0));auto meta=LayoutPropertyOutcome::Detail::Q(db,"SELECT stackable,stacksize FROM items WHERE id="+std::to_string(t.source.values.item_id)+" FOR UPDATE");Detail::Require(meta.RowCount()==1&&LayoutPropertyOutcome::Detail::Number(meta.begin()[0])==0&&LayoutPropertyOutcome::Detail::Number(meta.begin()[1])==t.after.maximum);auto cat=LayoutPropertyOutcome::Detail::Q(db,"SELECT revision FROM housing_catalogs WHERE catalog_key='"+db.Escape(t.after.placement.stored.placement->reservation.catalog_key)+"' FOR UPDATE");Detail::Require(cat.RowCount()==1&&LayoutPropertyOutcome::Detail::Number(cat.begin()[0])==t.after.placement.stored.current_catalog_revision);auto saved=LayoutPropertyOutcome::Detail::Q(db,"SELECT HEX(after_blob) FROM housing_live_item_receipts WHERE request_key='"+db.Escape(t.child_key)+"' AND completed=1 FOR UPDATE");Detail::Require(saved.RowCount()==1&&LayoutPropertyOutcome::Detail::Unhex(saved.begin()[0])==t.child_outcome);auto child=lease;child.pending_key=t.child_key;auto receipt=LiveItems::Service::ValidateRestartOutcome(db,child,&parent_key);if(!receipt)return {false,receipt.error};const auto& r=receipt.value;Detail::Require(r.action==LiveItems::Action::Store&&r.request_key==t.child_key&&CustodyCodec::Encode(r.stored.row)==CustodyCodec::Encode(t.source));LayoutPropertyOutcome::Snapshot actual=t.after;actual.placement={r.stored,r.room};actual.placement.stored.current_catalog_revision=LayoutPropertyOutcome::Detail::Number(cat.begin()[0]);actual.crate=r.crate_allocation;
 if(r.house_effect){Detail::Require(!r.house_effect->minted&&r.house_effect->before.house_id==t.house_before_id&&r.house_effect->before.revision==t.house_before_revision&&r.house_effect->before.interior&&r.house_effect->after.interior&&HouseBinding::SamePhysicalInterior(*r.house_effect->before.interior,*r.house_effect->after.interior));auto h=std::make_shared<HouseBinding::Binding>(r.house_effect->after);h->pending_key.clear();actual.house=h;}else actual.house.reset();
 Detail::Require(LayoutCrate::Same(t.crate_before,r.crate_before)&&LayoutPropertyOutcome::Detail::Same(actual,t.after));return {true,LiveItems::Error::None};
 }catch(...){return {false,LiveItems::Error::Conflict};}
}
// Called only after exact aggregate outcome validation, during its existing
// exclusive transaction. This is neither memory ACK nor an authority source.
inline void PublishHouses(Database& db,const std::vector<Outcome>& tokens,const std::string& key){for(const auto& t:tokens)if(t.after.house){const auto& h=*t.after.house;auto r=LayoutPropertyOutcome::Detail::Q(db,"UPDATE housing_house_instances SET pending_request_key='"+db.Escape(key)+"' WHERE house_id="+std::to_string(h.house_id)+" AND revision="+std::to_string(h.revision)+" AND pending_request_key IS NULL");Detail::Require(r.RowsAffected()==1);}}
inline void ReleaseHouses(Database& db,const std::vector<Outcome>& tokens,const std::string& key){for(const auto& t:tokens)if(t.after.house){const auto& h=*t.after.house;auto r=LayoutPropertyOutcome::Detail::Q(db,"UPDATE housing_house_instances SET pending_request_key=NULL WHERE house_id="+std::to_string(h.house_id)+" AND revision="+std::to_string(h.revision)+" AND pending_request_key='"+db.Escape(key)+"'");Detail::Require(r.RowsAffected()==1);}}
}
#endif
